class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> list[Optional[ListNode]]:
        length = 0
        curr = head
        while curr:
            length += 1
            curr = curr.next
        base_size = length // k
        extra = length % k
        res = []
        curr = head
        for i in range(k):
            part_head = curr
            part_len = base_size + (1 if i < extra else 0)
            for _ in range(part_len - 1):
                if curr:
                    curr = curr.next
            if curr:
                nxt = curr.next
                curr.next = None
                curr = nxt
            res.append(part_head)
        return res

class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        int length = 0;
        ListNode* curr = head;
        while (curr) { length++; curr = curr->next; }
        int baseSize = length / k;
        int extra = length % k;
        vector<ListNode*> res(k, nullptr);
        curr = head;
        for (int i = 0; i < k; i++) {
            res[i] = curr;
            int partLen = baseSize + (i < extra ? 1 : 0);
            for (int j = 0; j < partLen - 1 && curr; j++) curr = curr->next;
            if (curr) {
                ListNode* nxt = curr->next;
                curr->next = nullptr;
                curr = nxt;
            }
        }
        return res;
    }
};

class Solution {
    public ListNode[] splitListToParts(ListNode head, int k) {
        int length = 0;
        ListNode curr = head;
        while (curr != null) { length++; curr = curr.next; }
        int baseSize = length / k;
        int extra = length % k;
        ListNode[] res = new ListNode[k];
        curr = head;
        for (int i = 0; i < k; i++) {
            res[i] = curr;
            int partLen = baseSize + (i < extra ? 1 : 0);
            for (int j = 0; j < partLen - 1 && curr != null; j++) curr = curr.next;
            if (curr != null) {
                ListNode nxt = curr.next;
                curr.next = null;
                curr = nxt;
            }
        }
        return res;
    }
}

var splitListToParts = function(head, k) {
    let length = 0;
    let curr = head;
    while (curr !== null) { length++; curr = curr.next; }
    const baseSize = Math.floor(length / k);
    const extra = length % k;
    const res = [];
    curr = head;
    for (let i = 0; i < k; i++) {
        const partHead = curr;
        const partLen = baseSize + (i < extra ? 1 : 0);
        for (let j = 0; j < partLen - 1 && curr !== null; j++) curr = curr.next;
        if (curr !== null) {
            const nxt = curr.next;
            curr.next = null;
            curr = nxt;
        }
        res.push(partHead);
    }
    return res;
};
